def dependency_of_fetches_single(fetches, op):
    """
    Check that op is in the subgraph induced by the dependencies of fetches.

    Args:
        fetches: An argument to `sess.run`.
        op (tf.Operation or tf.Tensor):

    Returns:
        bool: True if `fetches` depends on `op`.
    """
    if isinstance(fetches, tf.Operation):
        return fetches.name in op.inputs
    elif isinstance(fetches, tf.Tensor):
        return fetches.name in op.inputs
    elif isinstance(fetches, tf.Variable):
        return fetches.name in op.inputs
    else:
        return False


